package controller;

import javafx.fxml.FXML;
import javafx.scene.control.Button;
import view.controllers.AbstractMiniGameController;

/**
 * The Controller related to the main.fxml GUI.
 *
 */
public final class UIController extends AbstractMiniGameController {

    @FXML
    private Button btn;

    /**
     * The handler for the click event generated by the 'btn' button.
     * @throws InterruptedException 
     */
    @FXML
    public void btnOnClickHandler() throws InterruptedException {
    	this.getAgentTimer().setTime(30);
    	this.getAgentTimer().start();       
    }

}
